import { execFile } from "node:child_process";
import { promisify } from "node:util";

import ts from "typescript";

export type ContractFileMap = Map<string, string>;

const execFileAsync = promisify(execFile);
export const GENERATED_HEADER =
	"// Generated by scripts/contracts/database-contracts.ts. Do not edit.\n\n";
const CATEGORY_DIRECTORIES = {
	Tables: "tables",
	Views: "views",
	Functions: "functions",
	Enums: "enums",
	CompositeTypes: "composite-types",
} as const;

type CategoryName = keyof typeof CATEGORY_DIRECTORIES;
const CATEGORY_NAMES: CategoryName[] = [
	"Tables",
	"Views",
	"Functions",
	"Enums",
	"CompositeTypes",
];

function memberName(member: ts.TypeElement): string | null {
	if (!member.name) return null;
	if (ts.isIdentifier(member.name) || ts.isStringLiteral(member.name)) {
		return member.name.text;
	}
	return null;
}

function property(
	literal: ts.TypeLiteralNode,
	name: string,
): ts.PropertySignature {
	const result = literal.members.find(
		(member): member is ts.PropertySignature =>
			ts.isPropertySignature(member) && memberName(member) === name,
	);
	if (!result?.type) throw new Error(`Supabase output is missing ${name}.`);
	return result;
}

function typeLiteral(node: ts.TypeNode, label: string): ts.TypeLiteralNode {
	if (!ts.isTypeLiteralNode(node)) {
		throw new Error(`Expected ${label} to be a type literal.`);
	}
	return node;
}

export function pascalCase(value: string): string {
	return value
		.split(/[^a-zA-Z0-9]+/u)
		.filter(Boolean)
		.map((part) => part.charAt(0).toUpperCase() + part.slice(1))
		.join("");
}

function pathSegment(value: string): string {
	return value.replaceAll("_", "-").replace(/[^a-zA-Z0-9-]/gu, "-");
}

function printedType(
	printer: ts.Printer,
	sourceFile: ts.SourceFile,
	node: ts.TypeNode,
): string {
	return printer.printNode(ts.EmitHint.Unspecified, node, sourceFile).trim();
}

function relationModule(options: {
	typeName: string;
	typeSource: string;
}): string {
	const jsonImport = options.typeSource.includes("Json")
		? 'import type { Json } from "../../json.ts";\n\n'
		: "";
	return `${GENERATED_HEADER}${jsonImport}export type ${options.typeName} = ${options.typeSource};\n`;
}

function schemaModule(options: {
	schemaName: string;
	categories: Map<CategoryName, Array<{ name: string; typeName: string }>>;
	emptyTypes: Map<CategoryName, string>;
}): string {
	const schemaSegment = pathSegment(options.schemaName);
	const imports: Array<{ specifier: string; line: string }> = [];
	const categoryLines: string[] = [];

	for (const categoryName of CATEGORY_NAMES) {
		const entries = options.categories.get(categoryName) ?? [];
		for (const entry of entries) {
			const specifier = `../${CATEGORY_DIRECTORIES[categoryName]}/${schemaSegment}/${pathSegment(entry.name)}.ts`;
			imports.push({
				specifier,
				line: `import type { ${entry.typeName} } from "${specifier}";`,
			});
		}
		if (entries.length === 0) {
			categoryLines.push(
				`  ${categoryName}: ${options.emptyTypes.get(categoryName) ?? "Record<never, never>"};`,
			);
			continue;
		}
		categoryLines.push(`  ${categoryName}: {`);
		for (const entry of entries) {
			categoryLines.push(
				`    ${JSON.stringify(entry.name)}: ${entry.typeName};`,
			);
		}
		categoryLines.push("  };");
	}

	// Ordered by module path, which is what the formatter sorts by. Ordering by
	// the printed line instead sorts on the type name, and the two only agree
	// while every import comes from the same directory.
	const importBlock =
		imports.length > 0
			? `${imports
					.sort((a, b) => (a.specifier < b.specifier ? -1 : 1))
					.map((entry) => entry.line)
					.join("\n")}\n\n`
			: "";
	return `${GENERATED_HEADER}${importBlock}export type ${pascalCase(options.schemaName)}Schema = {\n${categoryLines.join("\n")}\n};\n`;
}

function databaseIndex(schemaNames: string[]): string {
	const imports = schemaNames.map(
		(schema) =>
			`import type { ${pascalCase(schema)}Schema } from "./schemas/${pathSegment(schema)}.ts";`,
	);
	const members = schemaNames.map(
		(schema) => `  ${JSON.stringify(schema)}: ${pascalCase(schema)}Schema;`,
	);
	return `${GENERATED_HEADER}${imports.join("\n")}\n\nexport type { Json } from "./json.ts";\n\nexport type Database = {\n${members.join("\n")}\n};\n\nexport type SchemaName = keyof Database;\nexport type PublicTableName = keyof Database["public"]["Tables"];\nexport type TableRow<Name extends PublicTableName> = Database["public"]["Tables"][Name]["Row"];\nexport type TableInsert<Name extends PublicTableName> = Database["public"]["Tables"][Name]["Insert"];\nexport type TableUpdate<Name extends PublicTableName> = Database["public"]["Tables"][Name]["Update"];\n`;
}

export async function generateSupabaseTypeSource(
	databaseUrl: string,
): Promise<string> {
	const { stdout } = await execFileAsync(
		"bunx",
		[
			"--no-install",
			"supabase",
			"gen",
			"types",
			"typescript",
			"--db-url",
			databaseUrl,
			"--schema",
			"public,shipbash_private",
		],
		{ maxBuffer: 16 * 1024 * 1024 },
	);
	return stdout;
}

function parseSupabaseSource(source: string): ts.SourceFile {
	const transpiled = ts.transpileModule(source, {
		compilerOptions: { target: ts.ScriptTarget.Latest },
		fileName: "database.ts",
		reportDiagnostics: true,
	});
	const firstError = transpiled.diagnostics?.find(
		(diagnostic) => diagnostic.category === ts.DiagnosticCategory.Error,
	);
	if (firstError) {
		throw new Error(
			`Supabase type output did not parse: ${ts.flattenDiagnosticMessageText(firstError.messageText, "\n")}`,
		);
	}
	return ts.createSourceFile(
		"database.ts",
		source,
		ts.ScriptTarget.Latest,
		true,
		ts.ScriptKind.TS,
	);
}

function addCategoryFiles(options: {
	categoryName: CategoryName;
	files: ContractFileMap;
	printer: ts.Printer;
	schemaName: string;
	schemaLiteral: ts.TypeLiteralNode;
	sourceFile: ts.SourceFile;
}): { emptyType?: string | undefined; entries: Array<{ name: string; typeName: string }> } {
	const categoryMember = property(options.schemaLiteral, options.categoryName);
	const categoryType = categoryMember.type;
	if (!categoryType) {
		throw new Error(`Supabase output is missing ${options.categoryName}.`);
	}
	if (!ts.isTypeLiteralNode(categoryType)) {
		return {
			emptyType: printedType(options.printer, options.sourceFile, categoryType),
			entries: [],
		};
	}

	const entries: Array<{ name: string; typeName: string }> = [];
	for (const item of categoryType.members) {
		if (!ts.isPropertySignature(item) || !item.type) {
			throw new Error(
				`Unsupported ${options.schemaName}.${options.categoryName} member; expected a typed property.`,
			);
		}
		const itemName = memberName(item);
		if (!itemName) {
			throw new Error(
				`Unsupported ${options.schemaName}.${options.categoryName} property name.`,
			);
		}
		const typeName = `${pascalCase(options.schemaName)}${pascalCase(itemName)}${options.categoryName.slice(0, -1)}`;
		const relativePath = `packages/control-plane/src/generated/database/${CATEGORY_DIRECTORIES[options.categoryName]}/${pathSegment(options.schemaName)}/${pathSegment(itemName)}.ts`;
		options.files.set(
			relativePath,
			relationModule({
				typeName,
				typeSource: printedType(options.printer, options.sourceFile, item.type),
			}),
		);
		entries.push({ name: itemName, typeName });
	}
	return {
		emptyType:
			entries.length === 0
				? printedType(options.printer, options.sourceFile, categoryType)
				: undefined,
		entries,
	};
}

function addSchemaFiles(options: {
	files: ContractFileMap;
	printer: ts.Printer;
	schemaLiteral: ts.TypeLiteralNode;
	schemaName: string;
	sourceFile: ts.SourceFile;
}): void {
	const categories = new Map<
		CategoryName,
		Array<{ name: string; typeName: string }>
	>();
	const emptyTypes = new Map<CategoryName, string>();
	for (const categoryName of CATEGORY_NAMES) {
		const category = addCategoryFiles({ ...options, categoryName });
		categories.set(categoryName, category.entries);
		if (category.emptyType) emptyTypes.set(categoryName, category.emptyType);
	}
	options.files.set(
		`packages/control-plane/src/generated/database/schemas/${pathSegment(options.schemaName)}.ts`,
		schemaModule({ schemaName: options.schemaName, categories, emptyTypes }),
	);
}

export function splitSupabaseTypes(source: string): ContractFileMap {
	const sourceFile = parseSupabaseSource(source);
	const aliases = sourceFile.statements.filter(ts.isTypeAliasDeclaration);
	const jsonAlias = aliases.find((alias) => alias.name.text === "Json");
	const databaseAlias = aliases.find((alias) => alias.name.text === "Database");
	if (!jsonAlias || !databaseAlias) {
		throw new Error("Supabase output is missing Json or Database.");
	}

	const printer = ts.createPrinter({ newLine: ts.NewLineKind.LineFeed });
	const databaseLiteral = typeLiteral(databaseAlias.type, "Database");
	const files: ContractFileMap = new Map();
	files.set(
		"packages/control-plane/src/generated/database/json.ts",
		`${GENERATED_HEADER}export type Json = ${printedType(printer, sourceFile, jsonAlias.type)};\n`,
	);

	const schemaNames: string[] = [];
	for (const schemaMember of databaseLiteral.members) {
		if (!ts.isPropertySignature(schemaMember) || !schemaMember.type) {
			throw new Error(
				"Unsupported Database member; expected a typed schema property.",
			);
		}
		const schemaName = memberName(schemaMember);
		if (!schemaName) {
			throw new Error("Unsupported Database schema property name.");
		}
		schemaNames.push(schemaName);
		const schemaLiteral = typeLiteral(schemaMember.type, schemaName);
		addSchemaFiles({ files, printer, schemaLiteral, schemaName, sourceFile });
	}

	files.set("packages/control-plane/src/generated/database/index.ts", databaseIndex(schemaNames));
	return files;
}
